def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    for op in ops:
        current_time = op[1]

        # Remove expired entries
        keys_to_remove = []
        for key, (value, write_time) in cache.items():
            if current_time >= write_time + ttl:
                keys_to_remove.append(key)
        for key in keys_to_remove:
            del cache[key]

        if op[0] == 'put':
            key = op[2]
            value = op[3]

            # If key exists, remove it first (will re-add at end for MRU)
            if key in cache:
                del cache[key]
            # If cache is at capacity and we're adding a new key, evict LRU
            elif len(cache) >= capacity:
                cache.popitem(last=False)  # Remove oldest (first) item

            # Add the new entry as most recently used
            cache[key] = (value, current_time)

        elif op[0] == 'get':
            key = op[2]

            if key in cache:
                value, write_time = cache[key]
                # Move to end to mark as most recently used
                del cache[key]
                cache[key] = (value, write_time)
                results.append(value)
            else:
                results.append(-1)

    return results

